content.css:
.accent-kpi-card {
  font-family: 'Segoe UI', system-ui, -apple-system, sans-serif;
  box-sizing: border-box;
  height: 100%;
  display: flex;
  flex-direction: column;
  overflow: auto;
  cursor: pointer;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  text-rendering: geometricPrecision;
}
@supports (-moz-appearance: none) {
  .accent-kpi-card {
    scrollbar-width: thin;
    scrollbar-color: var(--kpi-scrollbar-thumb, rgba(96, 94, 92, 0.55)) var(--kpi-scrollbar-track, rgba(96, 94, 92, 0.12));
  }
}
.accent-kpi-card::-webkit-scrollbar {
  width: 8px;
  height: 8px;
}
.accent-kpi-card::-webkit-scrollbar-thumb {
  background: var(--kpi-scrollbar-thumb, rgba(96, 94, 92, 0.55));
  border-radius: 4px;
}
.accent-kpi-card::-webkit-scrollbar-track {
  background: var(--kpi-scrollbar-track, rgba(96, 94, 92, 0.12));
}
.accent-kpi-card::-webkit-scrollbar-corner {
  background: transparent;
}
.accent-kpi-card .kpi-accent {
  height: 3px;
  width: 100%;
  flex-shrink: 0;
  border-radius: 7px 7px 0 0;
}
.accent-kpi-card .kpi-body {
  flex: 1 0 auto;
  min-height: min-content;
  padding: 7px 14px 6px;
  display: flex;
  flex-direction: column;
  justify-content: center;
}
.accent-kpi-card .kpi-value-row {
  display: flex;
  align-items: baseline;
  gap: 8px;
  line-height: 1;
}
.accent-kpi-card .kpi-value {
  font-size: 30px;
  font-weight: 700;
  color: #023864;
  font-variant-numeric: tabular-nums;
}
.accent-kpi-card .subtitle-value {
  font-size: 16px;
  color: #605E5C;
  font-weight: 400;
}
.accent-kpi-card .delta {
  display: inline-block;
  align-self: flex-start;
  white-space: nowrap;
  font-size: 11px;
  font-weight: 700;
  margin-top: 4px;
  padding: 1px 8px;
  border-radius: 10px;
  line-height: 1.35;
}
.accent-kpi-card .delta-good {
  color: #0F7A2C;
  background: #e4f5e9;
}
.accent-kpi-card .delta-bad {
  color: #9E2F24;
  background: #f9e6e4;
}
.accent-kpi-card .delta-neutral {
  color: #605E5C;
  background: #eeecea;
}
.accent-kpi-card .kpi-caption {
  font-size: 11px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.3px;
  color: #023864;
  margin: 0 0 2px 0;
  line-height: 1.2;
}
.accent-kpi-card .kpi-header {
  min-height: 100%;
  display: flex;
  align-items: center;
  font-weight: 700;
  line-height: 1.15;
  padding: 0 2px;
  white-space: normal;
}
.accent-kpi-card.wrap .kpi-value-row {
  flex-wrap: wrap;
}
.accent-kpi-card.wrap .kpi-value,
.accent-kpi-card.wrap .subtitle-value,
.accent-kpi-card.wrap .kpi-caption {
  white-space: normal;
  overflow-wrap: anywhere;
}
.accent-kpi-card.wrap .delta {
  white-space: normal;
  overflow-wrap: anywhere;
}
.accent-kpi-card.selected {
  outline: 2px solid #1F908C;
  outline-offset: -2px;
}
.accent-kpi-card .kpi-landing {
  padding: 12px 14px;
  color: #605E5C;
}
.accent-kpi-card .kpi-landing .kpi-landing-title {
  font-size: 14px;
  font-weight: 700;
  color: #023864;
  margin-bottom: 4px;
}
.accent-kpi-card .kpi-landing .kpi-landing-body {
  font-size: 11px;
  line-height: 1.4;
}
